open(p,'w').write('''def transform(grid):
    # Each solid 3x3 monochrome block projects its color along its center row and column.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    emitters = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color != 0 and all(grid[rr][cc] == color for rr in range(r, r+3) for cc in range(c, c+3)):
                emitters.append((r+1, c+1, color))
    for r, c, color in emitters:
        for x in range(w):
            out[r][x] = color
        for y in range(h):
            out[y][c] = color
    # When rays of different colors cross, the crossing is left blank.
    for i, (r, c, color) in enumerate(emitters):
        for rr, cc, other in emitters[i+1:]:
            if color != other:
                out[r][cc] = 0
                out[rr][c] = 0
    return out
''')
